// Extrair dados do webhook e normalizar payload
const triggerItem = $input.first().json;
const payload = triggerItem.body ?? triggerItem;
const { webhookId, projectId, projectTitle, input, keywords, piiRedactions, embeddingId, callbackUrl, language } = payload;

const safeInput = typeof input === 'string' ? input.trim() : '';
const safeKeywords = Array.isArray(keywords) ? keywords.filter(Boolean).slice(0, 12) : [];
const embeddingPrompt = (safeKeywords.length > 0 ? safeKeywords.join(', ') : safeInput).slice(0, 600);

return [{
  json: {
    webhookId,
    projectId,
    projectTitle,
    embeddingId,
    callbackUrl,
    language: language || 'pt-BR',
    input: safeInput,
    keywords: safeKeywords,
    embeddingPrompt,
    piiRedactions: piiRedactions || 0,
    startedAt: new Date().toISOString()
  }
}];

// Preparar payload final para callback
const inputData = $node["Process Input1"].json;
const aiResponse = $node["Ollama RAG1"].json;
const vectorNodes = $node["Pinecone Search"].json;
const vectorResults = vectorNodes.matches || vectorNodes.results || [];

const totalLatencyMs = Date.now() - new Date(inputData.startedAt).getTime();
const rawText = aiResponse.response || JSON.stringify(aiResponse);

let parsedOutput;
let parseError = null;
try {
  const cleanText = rawText.replace(/```json/g, '').replace(/```/g, '').trim();
  parsedOutput = JSON.parse(cleanText);
} catch (e) {
  parseError = 'Failed to parse JSON';
  parsedOutput = {};
}

const ensureString = (v, f='') => typeof v === 'string' ? v.trim() : (typeof v === 'number' || typeof v === 'boolean' ? String(v) : f);
const clamp = (n, min, max) => Math.max(min, Math.min(max, n));
const normalizePriority = (p) => ['high','medium','low'].includes(String(p)) ? String(p) : 'medium';
const normalizeConfidence = (v) => { const n = Number(v); if (!Number.isFinite(n)) return 0; const s = n <= 1 ? n * 100 : n; return clamp(Math.round(s * 100)/100, 0, 100); }

const reqsRaw = Array.isArray(parsedOutput.technicalRequirements) ? parsedOutput.technicalRequirements : [];
const reqs = reqsRaw.slice(0,6).map((r, i) => ({
  id: ensureString(r?.id, `TR-${i+1}`),
  name: ensureString(r?.name || r?.title || r?.requirement, `Requirement ${i+1}`),
  detail: ensureString(r?.detail || r?.description || r?.notes, ''),
  priority: normalizePriority(r?.priority)
}));

const bomRaw = Array.isArray(parsedOutput.suggestedBOM) ? parsedOutput.suggestedBOM : [];
const bom = bomRaw.slice(0,6).map((b) => ({
  item: ensureString(b?.item || b?.component || b?.name, ''),
  quantity: ensureString(b?.quantity, '1'),
  notes: ensureString(b?.notes || b?.detail || b?.description, '')
}));

const normalizedOutput = {
  schemaVersion: 'mc_extract_v2',
  technicalRequirements: reqs,
  suggestedBOM: bom,
  suggestedCode: ensureString(parsedOutput.suggestedCode, ''),
  confidenceScore: normalizeConfidence(parsedOutput.confidenceScore),
  parseError,
  groundingCount: vectorResults.length,
  embeddingId: inputData.embeddingId
};

return [{
  json: {
    callbackUrl: inputData.callbackUrl,
    payload: {
      webhookId: inputData.webhookId,
      status: 'done',
      n8nExecutionId: $execution.id,
      latencyMs: totalLatencyMs,
      output: normalizedOutput
    }
  }
}];
